const fs=require('fs'),path=require('path'),zlib=require('zlib');
const b='';
const files=JSON.parse(zlib.gunzipSync(Buffer.from(b,'base64')).toString('utf8'));
for(const [name,data] of Object.entries(files)){const p=path.join(process.cwd(),name);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,data);}
console.log(`Zachitan v4 source materialized: ${Object.keys(files).length} files`);
